html:
{#- Certificate of conformity for a delivery, on the shared report kit: the
    goods, then for each the results behind its batch (coc_row_aggregate). -#}
{%- import "iso_compliance/templates/includes/report.html" as rp -%}
{{ rp.styles() }}
<div class="rp">
{{ rp.letterhead(letterhead(doc.company)) }}
{{ rp.title("Certificate of conformity", None, [
	("Certificate no.", doc.name),
	("Date", doc.get_formatted("posting_date")),
]) }}
{{ rp.grid([
	("Customer", (doc.customer_name or doc.customer) ~ ("<br><span class=\"rp-small\">" ~ doc.address_display ~ "</span>" if doc.address_display else "")),
	("Customer's order", (doc.po_no or "") ~ (" dated " ~ doc.get_formatted("po_date") if doc.po_date else "")),
	("Delivery note", doc.name ~ " dated " ~ doc.get_formatted("posting_date")),
	("Vehicle / LR no.", (doc.lr_no ~ (" dated " ~ doc.get_formatted("lr_date") if doc.lr_date else "")) if doc.lr_no else ""),
]) }}

<div class="rp-h">Goods supplied</div>
<table class="rp-t">
	<thead><tr><th class="c" style="width:5%">Sl.</th><th style="width:14%">Item code</th><th>Description</th>
		<th style="width:14%">Batch no.</th><th class="r" style="width:11%">Quantity</th>
		<th style="width:16%">Inspection report</th><th class="c" style="width:10%">Result</th></tr></thead>
	<tbody>
	{%- for row in doc.items -%}
	{%- set qi = frappe.get_doc("Quality Inspection", row.quality_inspection) if row.quality_inspection else None -%}
	<tr>
		<td class="c">{{ loop.index }}</td>
		<td>{{ row.item_code }}</td>
		<td>{{ row.item_name }}</td>
		<td>{{ row.batch_no or "" }}</td>
		<td class="r n">{{ row.get_formatted("qty") }} {{ row.uom }}</td>
		<td>{{ row.quality_inspection or "" }}</td>
		<td class="c">{% if qi %}{{ "OK" if qi.status == "Accepted" else qi.status }}{% endif %}</td>
	</tr>
	{%- endfor -%}
	</tbody>
</table>

{%- set ns_c = namespace(list=[]) -%}
{%- for row in doc.items -%}
{%- set agg = coc_row_aggregate(row) -%}
{%- if agg.parameters -%}
{%- if agg.concessions %}{% set ns_c.list = ns_c.list + agg.concessions %}{% endif -%}
<table class="rp-t" style="margin-top:10pt">
	<thead>
	<tr><th colspan="{{ 6 if agg.has_balloons else 5 }}">Test results: {{ row.item_code }}{% if row.batch_no %}, batch {{ row.batch_no }}{% endif %}{% if agg.work_orders %}, Work Order {{ agg.work_orders | join(", ") }}{% endif %}
		<div style="font-weight:normal" class="rp-small">Based on
		{%- if agg.outgoing %} despatch inspection {{ agg.outgoing }};{% endif -%}
		{%- if agg.pdi %} final inspection {{ agg.pdi | join(", ") }};{% endif -%}
		{%- if agg.incoming %} receipt inspection {{ agg.incoming | join(", ") }};{% endif -%}
		{%- if agg.in_process_count %} {{ agg.in_process_count }} in-process inspection{{ "s" if agg.in_process_count > 1 }};{% endif %}
		n is the number of readings behind each result.</div></th></tr>
	<tr>{% if agg.has_balloons %}<th class="c" style="width:5%">No.</th>{% endif %}<th>Parameter</th><th style="width:24%">Specification</th><th class="c" style="width:6%">n</th>
		<th style="width:20%">Observed (min &ndash; max)</th><th class="c" style="width:12%">Result</th></tr>
	</thead>
	<tbody>
	{%- for p in agg.parameters -%}
	<tr>
		{% if agg.has_balloons %}<td class="c">{{ p.balloon }}</td>{% endif %}
		<td>{{ p.specification }}{% if p["class"] == "CTQ" %} (CTQ){% endif %}</td>
		<td class="n">{% if p.limits %}{{ p.spec }}{% if p.spec %}, {% endif %}{{ p.limits }}{% else %}{{ p.spec or "" }}{% if p.min_spec is not none or p.max_spec is not none %} {{ p.min_spec if p.min_spec is not none else "" }} &ndash; {{ p.max_spec if p.max_spec is not none else "" }}{% endif %}{% endif %}</td>
		<td class="c">{{ p.n or "" }}</td>
		<td class="n">{%- if p.numeric and p.obs_min is not none -%}{{ p.obs_min }}{% if p.obs_min != p.obs_max %} &ndash; {{ p.obs_max }}{% endif %}
			{%- elif p["values"] -%}{{ p["values"] | join(", ") }}{%- endif -%}</td>
		<td class="c">{% if p.ok %}OK{% elif p.concession %}Concession{% else %}<span class="rp-nok">NOT OK</span>{% endif %}</td>
	</tr>
	{%- endfor -%}
	</tbody>
</table>
{%- endif -%}
{%- endfor -%}

<div class="rp-statement">
	We hereby certify that the goods listed above have been manufactured, inspected and tested in
	accordance with the applicable specifications and the customer's requirements, and conformed to them
	at the time of despatch{% if ns_c.list %}, except as permitted under concession {{ ns_c.list | unique | join(", ") }}{% endif %}.
</div>

{{ rp.signoff([("Inspected by", "", none), ("Authorised signatory, for " ~ doc.company, "", none)]) }}
{{ rp.footer("HCCPL/QMS/FRM-030", "Issue 01 / Rev 01", doc.name, "DRAFT: delivery note not submitted" if doc.docstatus == 0 else None) }}
</div>
